from scipy.optimize import least_squares
def f(p):
    return p[0]*T**p[1]*(1+p[2]*eps**p[3]) 
r=least_squares(lambda p: f(p)-sigma,[10,0.5,0.1,1])
print(r.x, np.mean((f(r.x)-sigma)**2)/np.var(sigma))
def g(p):
    return p[0]*T**p[1] + p[2]*np.log(1+p[3]*eps)*T**p[4]
r2=least_squares(lambda p: g(p)-sigma,[10,0.5,1,1,0.5])
